{
  "technical_and_design_decisions": [
    "Use Apache Curator / Zookeeper client namespace capabilities to isolate ZooKeeper metadata dynamically per tenant profile (U1).",
    "Modify the XD Shell authentication mechanism to support interactive password prompt using console mask to prevent plain-text logging or file persistence (U2).",
    "Establish a Git maintenance branch branching strategy (e.g., 1.0.x) and configure corresponding CI job builds (U3).",
    "Remove deprecated module definition download endpoints and methods across core, Shell, and Admin-UI components (U4).",
    "Perform a technical spike to evaluate ZooKeeper-based dynamic port registration vs. Load Balancer endpoints for xd-shell connection, followed by implementing ZooKeeper registration for Admin Server random ports (U5).",
    "Upgrade Kafka client dependencies to the new consumer API version and resolve test failures associated with partition assignment and commit offsets (U6).",
    "Conduct a research spike on Motion-JPEG streaming over HTTP/RTSP and evaluate OpenCV platform compatibility across supported JVM environments (U7).",
    "Expose a configurable YAML property (`servers.yml`) to toggle message rate aggregation and rendering in the cluster view (U8)."
  ],
  "assumptions": [
    "Development work will be carried out by a single full-stack Java developer familiar with Spring Framework, Spring XD/Cloud Data Flow, ZooKeeper, and Kafka.",
    "Target environment runs on Java 17+ and uses standard Spring Boot externalized configuration mechanisms.",
    "ZooKeeper cluster infrastructure is available and accessible for tenant namespace testing.",
    "Spikes (U5 and U7) are intended to deliver architectural decision records (ADRs) and initial feasibility prototypes rather than full production pipeline deployment."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement ZK Tenant Namespace Configuration (U1)",
      "activity_description": "Add support in Curator/ZooKeeper configuration to set tenant-specific namespaces for metadata isolation, including configuration property wiring and unit/integration tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Interactive Admin Authentication in Shell (U2)",
      "activity_description": "Implement masked interactive prompt for username and password in xd-shell CLI when connecting to Admin Server, ensuring credentials are not saved to disk or log files.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Maintenance Branch & CI/CD Pipeline Setup (U3)",
      "activity_description": "Create git maintenance branch for minor releases (e.g., 1.0.x) and configure build automation scripts and CI server pipelines.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Deprecated Module Registry & UI Cleanup (U4)",
      "activity_description": "Remove deprecated functions related to module definition downloads across core engine, xd-shell, and Admin-UI codebases.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Admin Server Random Port Discovery Spike & Implementation (U5)",
      "activity_description": "Research xd-shell connection options via ZK vs LB, and implement ZK service registration/lookup for Tomcat dynamic ports.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Kafka Consumer Upgrade & Test Fixes (U6)",
      "activity_description": "Update Kafka message bus dependencies to the rewritten consumer API and resolve failing integration test suites.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Motion-JPEG & Facial Analytics Feasibility Spike (U7)",
      "activity_description": "Research Motion-JPEG stream ingestion feasibility, evaluate OpenCV native library compatibility across platforms, and produce technical design specifications.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Message Rate Toggle in Cluster View Configuration (U8)",
      "activity_description": "Add `servers.yml` configuration parameter to enable/disable message rate metrics calculation and update Admin-UI / REST controllers accordingly.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Integration Testing & Validation",
      "activity_description": "Execute comprehensive integration test suites across modified modules, verify multi-tenant isolation, and validate release stability.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 110
  }
}
